import * as T from 'three';
import {MeshBVH} from 'three-mesh-bvh';
import {outgoing,ceiling} from './small-mirror-optics.js';
export function installCeiling({scene,camera,controls,meshes,manifest,state,rays,renderer}){
 const panel=document.createElement('details');panel.open=true;panel.innerHTML=`<summary>天井へ投影（高さ3m）</summary><p>床から天井まで3,000mm。大鏡を外し、小鏡からの像を表示します。頭部・大鏡は半透明の組立参考表示で重ねられます。</p><label><input id="ceiling-on" type="checkbox"> 天井投影を表示</label><br><label>設置台の高さ mm <input id="table-height" type="number" min="0" max="2000" step="50" value="0" style="width:80px"></label><br><label><input id="ceiling-head" type="checkbox"> 頭部を残して遮蔽を確認</label><br><label><input id="ceiling-structure" type="checkbox" checked> 試作機の全構造を重ねる（参考表示）</label><p>半透明の部品は位置確認用で、天井への光を遮りません。実際に頭部を残す場合は上の遮蔽確認を選択してください。</p><button id="ceiling-machine">試作機・固定機構を拡大</button><br><select id="ceiling-source"><option value="face">オーキャンv2</option><option value="chart">方向付き格子</option></select><br><button id="ceiling-overall">床・試作機・天井の全景</button><button id="ceiling-close">天井を見上げる</button><p id="ceiling-status"></p><p>点光源・表面鏡の幾何投影です。実際の焦点、ぼけ、明るさ、裏面鏡の二重像はこの3D表示に含みません。床置き時の3m天井は公称の焦点調整範囲（最大1.27m）を超えるため、実機で鮮明に映る保証はありません。</p>`;
 document.querySelector('aside').prepend(panel);const $=id=>document.getElementById(id);camera.far=20000;camera.updateProjectionMatrix();
 const group=new T.Group();group.visible=false;scene.add(group);const material=new T.MeshBasicMaterial({color:0x5b6570,side:T.DoubleSide,transparent:true,opacity:.25,depthWrite:false});const ceilingMesh=new T.Mesh(new T.PlaneGeometry(6200,6200),material);group.add(ceilingMesh);
 const structure=new T.Group();group.add(structure);const structureMeshes=new Map();for(const p of manifest.parts){const source=meshes[p.name];if(!source||p.template)continue;const mat=source.material.clone();mat.transparent=true;mat.opacity=.22;mat.depthWrite=false;const copy=new T.Mesh(source.geometry,mat);copy.name=p.name;structure.add(copy);structureMeshes.set(p.name,copy);}
 const floor=new T.GridHelper(6200,31,0x78958f,0x334842);floor.rotation.x=Math.PI/2;group.add(floor);
 const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=720;const ctx=canvas.getContext('2d');const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;
 const projection=new T.Mesh(new T.BufferGeometry(),new T.MeshBasicMaterial({map:texture,side:T.DoubleSide,toneMapped:false}));group.add(projection);let beams=new T.LineSegments(new T.BufferGeometry(),new T.LineBasicMaterial({color:0xf3c477,transparent:true,opacity:.5}));group.add(beams);
 let saved=null,active=false,table=0,center=new T.Vector3(),interval=null,loading=false;const trees=new Map();let imageSource='';
 function label(text){const c=document.createElement('canvas');c.width=1024;c.height=128;const x=c.getContext('2d');x.font='52px sans-serif';x.fillStyle='white';x.fillText(text,10,80);const sp=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c),depthTest:false}));sp.scale.set(1400,175,1);group.add(sp);return sp}const heightLabel=label('床 → 天井 3,000 mm');
 function chart(){ctx.fillStyle='#17444d';ctx.fillRect(0,0,1280,720);for(let y=0;y<9;y++)for(let x=0;x<16;x++){ctx.fillStyle=(x+y)%2?'#327781':'#244751';ctx.fillRect(x*80,y*80,79,79)}ctx.strokeStyle='#f8cb76';ctx.lineWidth=12;ctx.strokeRect(8,8,1264,704);ctx.fillStyle='white';ctx.font='bold 64px sans-serif';ctx.textAlign='center';ctx.fillText('TOP ↑',640,90);ctx.fillText('LEFT',150,370);ctx.fillText('RIGHT',1110,370);ctx.fillText('BOTTOM',640,675);texture.needsUpdate=true;imageSource='方向付き格子';}
 async function frame(){if(!active||loading)return;if($('ceiling-source').value==='chart'){chart();return;}loading=true;try{const r=await fetch('/api/frame?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error();const bitmap=await createImageBitmap(await r.blob());ctx.drawImage(bitmap,0,0,1280,720);bitmap.close();texture.needsUpdate=true;imageSource='オーキャンv2フレーム（約1秒ごとに更新）';}catch{const im=new Image();im.src='assets/small-mirror-study/open-campus-frame.jpg';try{await im.decode();ctx.drawImage(im,0,0,1280,720);texture.needsUpdate=true;imageSource='オーキャンv2保存フレーム';}catch{chart();}}finally{loading=false;if(active&&window.prototypeCeiling)window.prototypeCeiling.source=imageSource}}
 function visible(m){let o=m;while(o){if(!o.visible)return false;o=o.parent;}return true}
 function hideParts(){for(const p of manifest.parts){const m=meshes[p.name];if(!m)continue;const big=p.name==='mirror-glass'||p.name.startsWith('printed-mirror-')||p.name.startsWith('mirror-head-');const head=p.name==='face'||p.name==='magnet-carrier'||['head-upper','head-lower'].includes(p.name)||p.name.startsWith('head-seam-')||p.name.startsWith('head-alignment-')||p.name.startsWith('magnet-clear-');if(big||(!$('ceiling-head').checked&&head))m.visible=false;else if(saved&&p.name in saved.vis)m.visible=saved.vis[p.name];}meshes.head.visible=$('ceiling-head').checked; if($('ceiling-head').checked){meshes['head-upper'].visible=true;meshes['head-lower'].visible=true;meshes.face.visible=true;}}
 function update(){table=Number($('table-height').value);if(!Number.isFinite(table))table=0;table=Math.max(0,Math.min(2000,table));$('table-height').value=table;const floorZ=-182-table,ceilZ=floorZ+3000;ceilingMesh.position.z=ceilZ;floor.position.z=floorZ;heightLabel.position.set(2200,0,(floorZ+ceilZ)/2);hideParts();scene.updateMatrixWorld(true);structure.visible=$('ceiling-structure').checked;for(const[n,m]of structureMeshes)m.visible=!visible(meshes[n]);
 const blockers=manifest.parts.filter(p=>!p.template&&p.name!=='foldMirror-glass').map(p=>meshes[p.name]).filter(m=>m&&visible(m));for(const m of blockers)if(!trees.has(m)){m.geometry.computeBoundingBox();trees.set(m,new MeshBVH(m.geometry));}
 let positions=[],uvs=[],lines=[],hitCount=0,mirrorMiss=0,obscured=0,mins=new T.Vector3(Infinity,Infinity,Infinity),maxs=new T.Vector3(-Infinity,-Infinity,-Infinity);const nx=80,ny=45;
 function sample(u,v,check=true){const a=outgoing(state,u,v);if(!a||!a.inside)return{why:'mirror'};const end=ceiling(a.main,ceilZ);if(!end)return{why:'direction'};if(check){const ray=new T.Ray(a.main.origin,a.main.direction),L=end.distanceTo(a.main.origin);for(const m of blockers){const localRay=ray.clone().applyMatrix4(m.matrixWorld.clone().invert());if(!localRay.intersectsBox(m.geometry.boundingBox))continue;if(trees.get(m).raycastFirst(localRay,T.DoubleSide,.1,L-.1))return{why:'blocked'};}}return{a,end};}
 for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const mid=sample((x+.5)/nx,(y+.5)/ny);if(!mid.end){if(mid.why==='blocked')obscured++;else mirrorMiss++;continue;}hitCount++;const coords=[[x/nx,y/ny],[(x+1)/nx,y/ny],[(x+1)/nx,(y+1)/ny],[x/nx,(y+1)/ny]],corners=coords.map(([u,v])=>sample(u,v,false));if(corners.some(a=>!a.end))continue;for(const i of[0,1,2,0,2,3]){const p=corners[i].end;positions.push(p.x,p.y,p.z-.8);uvs.push(...coords[i]);mins.min(p);maxs.max(p);}if(x%16===8&&y%9===4)lines.push(...mid.a.main.origin.toArray(),...mid.end.toArray());}
 projection.geometry.dispose();projection.geometry=new T.BufferGeometry();projection.geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));projection.geometry.setAttribute('uv',new T.Float32BufferAttribute(uvs,2));projection.geometry.computeVertexNormals();beams.geometry.dispose();beams.geometry=new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(lines,3));center=positions.length?mins.clone().add(maxs).multiplyScalar(.5):new T.Vector3(0,0,ceilZ);ceilingMesh.position.x=center.x;ceilingMesh.position.y=center.y;
 $('ceiling-status').textContent=`天井：床から3,000mm／設置台${table}mm。小鏡から天井まで約${Math.round(ceilZ-state.foldMirror.position[2])}mm（鉛直）。投影サンプル${hitCount}/${nx*ny}、部品による遮蔽${obscured}、鏡外など${mirrorMiss}。大鏡${$('ceiling-head').checked?'のみ':'・頭部'}を外した表示。`;
 window.prototypeCeiling={enabled:true,floorZ,ceilingZ:ceilZ,tableHeightMM:table,ceilingAboveFloorMM:ceilZ-floorZ,structureVisible:structure.visible,referencePartCount:[...structureMeshes.values()].filter(m=>m.visible).length,headPresent:$('ceiling-head').checked,hitCount,obscured,mirrorMiss,source:imageSource};}
 function overview(){floor.visible=true;beams.visible=true;camera.fov=38;camera.updateProjectionMatrix();camera.position.set(4400,-4700,1700-table);controls.target.set(center.x*.3,center.y*.3,1100-table);controls.update()}
 function close(){floor.visible=false;beams.visible=false;camera.fov=65;camera.updateProjectionMatrix();camera.position.set(center.x-450,center.y-300,center.z-2600);controls.target.set(center.x-450,center.y,center.z);controls.update()}
 function toggle(){active=$('ceiling-on').checked;group.visible=active;if(active){saved={fov:camera.fov,vis:Object.fromEntries(Object.entries(meshes).map(([n,m])=>[n,m.visible])),camera:camera.position.clone(),target:controls.target.clone(),rays:rays.visible};for(const id of ['head-split-view','explode-face','shadow-view','magnet-view','head-connection-view','head','face','hardware','rays'])if($(id))$(id).disabled=true;rays.visible=false;chart();update();overview();frame();interval=setInterval(frame,1000);}else{clearInterval(interval);camera.fov=saved.fov;camera.updateProjectionMatrix();for(const[n,v]of Object.entries(saved.vis))meshes[n].visible=v;camera.position.copy(saved.camera);controls.target.copy(saved.target);rays.visible=saved.rays;for(const id of ['head-split-view','explode-face','shadow-view','magnet-view','head-connection-view','head','face','hardware','rays'])if($(id))$(id).disabled=false;window.prototypeCeiling={enabled:false};}}
 $('ceiling-structure').onchange=()=>{structure.visible=$('ceiling-structure').checked;if(active)update()};$('ceiling-machine').onclick=()=>{if(!active){$('ceiling-on').checked=true;toggle()}floor.visible=true;beams.visible=true;camera.fov=38;camera.updateProjectionMatrix();camera.position.set(760,-860,470);controls.target.set(-65,0,70);controls.update()};
 $('ceiling-on').onchange=toggle;$('ceiling-head').onchange=()=>{if(active)update()};$('table-height').onchange=()=>{if(active){update();overview()}};$('ceiling-source').onchange=frame;$('ceiling-overall').onclick=()=>{if(!active){$('ceiling-on').checked=true;toggle()}else overview()};$('ceiling-close').onclick=()=>{if(!active){$('ceiling-on').checked=true;toggle()}close()};
 if(new URLSearchParams(location.search).has('ceiling')){$('ceiling-on').checked=true;toggle();}
}
